    49  UA_StatusCode
    50  UA_SecureChannel_setSecurityPolicy(UA_SecureChannel *channel,
    51                                     const UA_SecurityPolicy *securityPolicy,
    52                                     const UA_ByteString *remoteCertificate) {
    53      /* Is a policy already configured? */
    54      if(channel->securityPolicy)
    55          return UA_STATUSCODE_BADINTERNALERROR;
    56
    57      channel->securityPolicy = securityPolicy;
    58      UA_StatusCode retval;
    59      if(channel->securityPolicy->certificateVerification != NULL) {
    60          retval = channel->securityPolicy->certificateVerification->
    61              verifyCertificate(channel->securityPolicy->certificateVerification->context, remoteCertificate);
    62
    63          if(retval != UA_STATUSCODE_GOOD)
    64              return retval;
    65      } else {
    66          UA_LOG_WARNING(channel->securityPolicy->logger, UA_LOGCATEGORY_SECURITYPOLICY,
    67                         "No PKI plugin set. Accepting all certificates");
    68      }
    69
    70      retval = securityPolicy->channelModule.
    71          newContext(securityPolicy, remoteCertificate, &channel->channelContext);
    72      if(retval != UA_STATUSCODE_GOOD)
    73          return retval;
    74
    75      retval = UA_ByteString_copy(remoteCertificate, &channel->remoteCertificate);
    76      if(retval != UA_STATUSCODE_GOOD)
    77          return retval;
    78
    79      UA_ByteString remoteCertificateThumbprint = {20, channel->remoteCertificateThumbprint};
    80      retval = securityPolicy->asymmetricModule.
    81          makeCertificateThumbprint(securityPolicy, &channel->remoteCertificate,
    82                                    &remoteCertificateThumbprint);
    83
    84      return retval;
    85  }
