    88  deleteMessage(UA_Message *me) {
    89      UA_ChunkPayload *cp;
    90      while((cp = SIMPLEQ_FIRST(&me->chunkPayloads))) {
    91          if(cp->copied)
    92              UA_ByteString_deleteMembers(&cp->bytes);
    93          SIMPLEQ_REMOVE_HEAD(&me->chunkPayloads, pointers);
    94          UA_free(cp);
    95      }
    96      UA_free(me);
    97  }
