   100  deleteLatestMessage(UA_SecureChannel *channel, UA_UInt32 requestId) {
   101      UA_Message *me = TAILQ_LAST(&channel->messages, UA_MessageQueue);
   102      if(!me)
   103          return;
   104      if(me->requestId != requestId)
   105          return;
   106
   107      TAILQ_REMOVE(&channel->messages, me, pointers);
   108      deleteMessage(me);
   109  }
